# GENERATED by prepare_clocked_vectors.py; predecessors unchanged.
# GENERATED by prepare_common_cpu_checks.py; ancestors unchanged.
"""Adapt verified instruction vectors to actual reset-domain outputs."""
import hashlib
import json
from pathlib import Path
import sys
import re
import run_system_vectors as base

ROOT = Path(__file__).resolve().parents[1]


def main():
    folder = ROOT / 'verification/net23/vectors'
    folder.mkdir(parents=True, exist_ok=True)
    base.OUT = folder
    base.MODELS = [p for p in base.MODELS if p not in ('sim/net19a/isa1_memory_system.sv', 'sim/net14c/video_raster_async_netlist.sv')] + [
        'hardware/clocked_reset/clocked_reset_netlist.sv', 'sim/net23/clock_models.sv', 'sim/net23/isa1_clocked_memory.sv', 'sim/net22/phase_packages.sv', 'sim/net22/video_common_async_netlist.sv']
    original = base.fixture

    def fixture(text, timed, refs):
        text = original(text, timed, refs)
        old = 'dut(clk,reset_n,power_good,run,boot'
        if text.count(old) != 1:
            raise ValueError('Unexpected CPU reset wiring')
        text = text.replace(old, "dut(memory.cpu_core_clk,memory.cpu_reset_n,1'b1,run,boot")
        # A physical reset must persist past the maximum RC assertion bound.
        text = text.replace('repeat(2)@(negedge clk);', 'repeat(6)@(negedge clk);')
        old = '@(negedge memory.backend_clk);#0.01;'
        if old not in text:
            raise ValueError('Vector fixture lacks bank seed staging')
        text = text.replace(old, 'wait(memory.safe===1);\n     ' + old)
        text = text.replace('isa1_memory ', 'isa1_clocked_memory ')
        old = 'memory(clk,video_clk,reset_n,power_good,'
        assert text.count(old)==1
        text = text.replace(old, 'memory(reset_n,power_good,power_good,')
        old = 'reg clk=0,video_clk=0,reset_n=0,power_good=1,run=0;'
        assert text.count(old)==1
        text = text.replace(old, 'reg reset_n=0,power_good=1,run=0;\n wire clk=memory.cpu_source,video_clk=memory.master_source;')
        text,count = re.subn(r' always #[0-9.]+ clk=~clk;\n', '', text)
        assert count==1
        text,count = re.subn(r' always #[0-9.]+ video_clk=~video_clk;\n', '', text)
        assert count==1
        if not timed:
            old = 'module tb_rtl_cpu;'
            assert text.count(old)==1
            text = text.replace(old, old + '\n defparam memory.reset_domains.CPU_PERIOD_NS=10, memory.reset_domains.MASTER_PERIOD_NS=3.5, memory.reset_domains.CPU_STARTUP_NS=100, memory.reset_domains.MASTER_STARTUP_NS=100;')
        return text

    base.fixture = fixture
    result = base.main()
    timed = '--timed' in sys.argv
    quick = '--quick' in sys.argv
    early = '--early' in sys.argv
    report_path = folder / ('verified-cpu' + ('-early' if early else '') + ('-timed' if timed else '-ideal') + ('-quick' if quick else '') + '.json')
    report = json.loads(report_path.read_text())
    report.update(scope='Instruction vectors with native reset/clock domains and actual CPU reset output; fixture-only architectural/MMIO/memory seeds occur after readiness. Native configured oscillator clocks; qualified oscillator VDD, analog supervisor forcepoint/RC conditional, no jitter/POR/board/PVT/MTBF signoff. Ideal mode explicitly scales oscillator period/startup parameters and is not physical frequency.',
                  supervisor_output_load_qualified=False)
    for name in ['tools/run_clocked_vectors_ideal.py', 'tools/prepare_clocked_vectors.py', 'tools/prepare_clocked_ideal.py', 'tools/build_clocked_reset.py', 'verification/net23/native/clocked_reset.xml']:
        report['sources'].append({'path': name, 'sha256': hashlib.sha256((ROOT / name).read_bytes()).hexdigest()})
    report_path.write_text(json.dumps(report, indent=2) + '\n')
    return result


if __name__ == '__main__':
    raise SystemExit(main())
